// Workflow 08 – Node: "Sign context request". Input from 07: the recovery
// result { incident_id, playbook_run_id, service_name, action_type, status, ... }.
// Builds the signed GET /api/machine/incidents/:id/context (BD-4) so the report
// uses the stored incident, AI analysis and timeline. Without an incident id
// (or signing config) the context step is skipped and only the input is used.
// ---- shared: HMAC signing (same scheme as backend/src/middleware/machine-auth.ts) ----
// canonical = timestamp + "." + nonce + "." + METHOD + "." + path + "." + rawBody
// header X-DC-Signature = "sha256=" + hex(HMAC-SHA256(secret, canonical))
const __crypto = require('crypto');
const HMAC_MAX_SKEW_SECONDS = 300;
const HMAC_MIN_SECRET_LENGTH = 32;
const HMAC_NONCE_PATTERN = /^[A-Za-z0-9_-]{16,200}$/;
const HMAC_SIGNATURE_PATTERN = /^sha256=[0-9a-f]{64}$/;

function hmacCanonical(timestamp, nonce, method, path, body) {
  return [String(timestamp), nonce, String(method).toUpperCase(), path, body].join('.');
}

function hmacSignature(secret, timestamp, nonce, method, path, body) {
  return 'sha256=' + __crypto.createHmac('sha256', secret)
    .update(hmacCanonical(timestamp, nonce, method, path, body), 'utf8').digest('hex');
}

function hmacSecret(value) {
  if (typeof value !== 'string' || value.length < HMAC_MIN_SECRET_LENGTH) {
    throw new Error('MACHINE_SIGNING_SECRET is missing or shorter than 32 characters.');
  }
  return value;
}

function hmacNonce() {
  return __crypto.randomBytes(24).toString('base64url');
}

// Timeout of a signed backend request (BACKEND_TIMEOUT_MS, 1-60 s, default 15 s).
function hmacTimeoutMs(env) {
  const raw = env.BACKEND_TIMEOUT_MS;
  const n = Number(raw);
  if (raw === undefined || raw === '' || !Number.isFinite(n)) return 15000;
  return Math.min(60000, Math.max(1000, Math.round(n)));
}

// Build a signed backend request. `path` must be the full request path (e.g.
// /api/machine/playbook-runs/<id>/start) because the backend signs req.originalUrl.
// Every call creates a NEW nonce and timestamp: a retry must call this again,
// never re-send an old request (the backend answers 409 "Replayed request").
function signedBackendRequest(env, method, path, payload, now) {
  const secret = hmacSecret(env.MACHINE_SIGNING_SECRET);
  const base = String(env.BACKEND_BASE_URL || '').replace(/\/+$/, '');
  if (!/^https?:\/\//.test(base)) throw new Error('BACKEND_BASE_URL is not configured.');
  const body = payload === undefined ? '' : JSON.stringify(payload);
  const timestamp = Math.floor((now || Date.now()) / 1000);
  const nonce = hmacNonce();
  return {
    method: method.toUpperCase(),
    url: base + path,
    path,
    body,
    timeout_ms: hmacTimeoutMs(env),
    headers: {
      'X-DC-Timestamp': String(timestamp),
      'X-DC-Nonce': nonce,
      'X-DC-Signature': hmacSignature(secret, timestamp, nonce, method, path, body),
    },
  };
}

// Verify an incoming signed request (backend -> n8n). Returns { ok, status, reason }.
// `seen` is a plain object used as the replay store (workflow static data).
function verifySignedRequest(secret, headers, method, path, rawBody, seen, nowMs) {
  const now = nowMs || Date.now();
  const h = {};
  for (const [k, v] of Object.entries(headers || {})) h[String(k).toLowerCase()] = v;
  const ts = h['x-dc-timestamp'];
  const nonce = h['x-dc-nonce'];
  const sig = h['x-dc-signature'];
  if (!ts || !nonce || !sig) return { ok: false, status: 401, reason: 'Signed request headers are required.' };
  if (!/^\d{1,12}$/.test(String(ts))) return { ok: false, status: 401, reason: 'Invalid request timestamp.' };
  if (Math.abs(now / 1000 - Number(ts)) > HMAC_MAX_SKEW_SECONDS) {
    return { ok: false, status: 401, reason: 'Signed request is outside the 5 minute window.' };
  }
  if (!HMAC_NONCE_PATTERN.test(nonce) || !HMAC_SIGNATURE_PATTERN.test(sig)) {
    return { ok: false, status: 401, reason: 'Invalid request signature.' };
  }
  const expected = Buffer.from(hmacSignature(hmacSecret(secret), Number(ts), nonce, method, path, rawBody), 'utf8');
  const given = Buffer.from(sig, 'utf8');
  if (given.length !== expected.length || !__crypto.timingSafeEqual(given, expected)) {
    return { ok: false, status: 401, reason: 'Invalid request signature.' };
  }
  // Replay protection: each nonce once within 15 minutes (3x the skew window).
  const cutoff = now - 15 * 60 * 1000;
  for (const [k, at] of Object.entries(seen)) if (at < cutoff) delete seen[k];
  if (seen[nonce]) return { ok: false, status: 409, reason: 'Replayed request.' };
  seen[nonce] = now;
  return { ok: true, status: 200, reason: null };
}
// ---- end shared: HMAC ----
// ---- shared: common helpers ----
const SECRET_PATTERNS = [
  /(authorization|api[_-]?key|token|secret|password|signature)(["'\s:=]+)([^\s"',}]+)/gi,
  /\bgsk_[A-Za-z0-9]{10,}\b/g,          // Groq keys
  /\bgh[pousr]_[A-Za-z0-9]{20,}\b/g,     // GitHub tokens
  /\beyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{5,}\b/g, // JWTs
  /https:\/\/hooks\.slack\.com\/[^\s"']+/g,
  /https:\/\/discord(?:app)?\.com\/api\/webhooks\/[^\s"']+/g,
];

function redact(text) {
  let out = String(text == null ? '' : text);
  for (const re of SECRET_PATTERNS) {
    // Only the first pattern has capture groups (key + separator are kept).
    out = out.replace(re, (m, a, b) => (typeof a === 'string' && typeof b === 'string' ? a + b + '[REDACTED]' : '[REDACTED]'));
  }
  return out;
}

function truncate(text, max) {
  const s = String(text == null ? '' : text);
  return s.length > max ? s.slice(0, max - 1) + '…' : s;
}

function envInt(env, name, fallback, min, max) {
  const raw = env[name];
  const n = raw === undefined || raw === '' ? fallback : Number(raw);
  if (!Number.isFinite(n)) return fallback;
  return Math.min(max, Math.max(min, Math.round(n)));
}

function envNumber(env, name, fallback) {
  const n = Number(env[name]);
  return env[name] === undefined || env[name] === '' || !Number.isFinite(n) ? fallback : n;
}

// Classify the output of an HTTP Request node that runs with
// "full response" + "never error" + onError=continueRegularOutput.
// kind: ok | timeout | unavailable | auth | rate_limited | not_found | not_implemented | invalid | server_error | client_error
function classifyHttp(item, opts) {
  const o = opts || {};
  if (item && item.error) {
    const msg = String(item.error.message || item.error.description || item.error || '');
    const code = String(item.error.code || '');
    if (/timeout|ETIMEDOUT|ESOCKETTIMEDOUT|ECONNABORTED/i.test(msg + code)) {
      return { kind: 'timeout', retryable: true, status: null, message: 'Request timed out.' };
    }
    return { kind: 'unavailable', retryable: true, status: null, message: redact(truncate(msg || 'Connection failed.', 300)) };
  }
  const status = Number(item && item.statusCode);
  if (!status) return { kind: 'invalid', retryable: false, status: null, message: 'No HTTP status in response.' };
  if (status >= 200 && status < 300) return { kind: 'ok', retryable: false, status, message: null };
  const bodyMsg = item.body && typeof item.body === 'object' ? (item.body.message || (item.body.error && (item.body.error.message || item.body.error))) : item.body;
  const message = redact(truncate(bodyMsg || ('HTTP ' + status), 300));
  if (status === 401 || status === 403) return { kind: 'auth', retryable: false, status, message };
  if (status === 429) return { kind: 'rate_limited', retryable: true, status, message };
  if (status === 404 && o.notFoundMeansNotImplemented) return { kind: 'not_implemented', retryable: false, status, message: 'Backend endpoint is not implemented yet (404).' };
  if (status === 404) return { kind: 'not_found', retryable: false, status, message };
  if (status === 503 && o.serviceUnavailableMeansNotConfigured) return { kind: 'not_configured', retryable: true, status, message };
  if (status >= 500) return { kind: 'server_error', retryable: true, status, message };
  return { kind: 'client_error', retryable: false, status, message };
}

// Standard investigation result (automation/schemas/investigation-output.schema.json).
function investigationResult(source, ctx, fields) {
  const f = fields || {};
  return {
    incident_id: ctx.incident_id || null,
    source,
    status: f.status,                 // evidence_found | no_evidence | unavailable | not_configured | invalid_input
    ok: f.status === 'evidence_found' || f.status === 'no_evidence',
    summary: f.summary || '',
    findings: f.findings || [],
    evidence: f.evidence || [],
    confidence: typeof f.confidence === 'number' ? Math.max(0, Math.min(1, f.confidence)) : 0,
    window: f.window || null,
    error: f.error || null,
    collected_at: new Date().toISOString(),
  };
}

// URLSearchParams is not available in the n8n task-runner sandbox (n8n 2.x).
function toQuery(params) {
  return Object.entries(params)
    .filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(String(v)))
    .join('&');
}

function isUuid(v) {
  return typeof v === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v);
}

// Investigation input (from workflow 01 / 05). Returns { ok, ctx, error }.
function readInvestigationInput(json) {
  const j = json || {};
  const started = j.started_at ? new Date(j.started_at) : null;
  const errors = [];
  if (!j.service_name || typeof j.service_name !== 'string' || !/^[A-Za-z0-9_.:-]{1,100}$/.test(j.service_name)) {
    errors.push('service_name is required (letters, digits, _ . : - only).');
  }
  if (!started || isNaN(started.getTime())) errors.push('started_at must be an ISO timestamp.');
  if (j.incident_id != null && !isUuid(j.incident_id)) errors.push('incident_id must be a UUID or null.');
  return {
    ok: errors.length === 0,
    error: errors.join(' ') || null,
    ctx: {
      incident_id: j.incident_id || null,
      service_name: j.service_name,
      alert_name: j.alert_name || null,
      severity: j.severity || null,
      started_at: started && !isNaN(started.getTime()) ? started.toISOString() : null,
    },
  };
}
// ---- end shared: common ----
const input = $input.first().json || {};
let request = null;
let sign_error = null;
if (isUuid(input.incident_id)) {
  try {
    request = signedBackendRequest($env, 'GET', '/api/machine/incidents/' + input.incident_id + '/context');
  } catch (e) {
    sign_error = String(e.message || e);
  }
}
return [{ json: { input, request, skip_context: !request, sign_error } }];

// Workflow 08 – Postmortem (owner: Tharindu)
